def f(g):
    res=[]
    for row in g:
        w=len(row)
        nz=[(k,v) for k,v in enumerate(row) if v!=0]
        cands=[]
        for p in range(1,w+1):
            mm={}
            ok=True
            for k,v in nz:
                if k%p in mm and mm[k%p]!=v: ok=False; break
                mm[k%p]=v
            if ok: cands.append((p,len(mm),mm))
        cand=max(cands,key=lambda x:(x[1],-x[0]))
        p,cnt,mm=cand
        outrow=[]
        for k in range(w):
            if row[k]==0 and k%p in mm:
                outrow.append(mm[k%p])
            else:
                outrow.append(row[k])
        res.append(outrow)
    return res
